// ==== Custom Uniform Controls ====

//@float min=0.0 max=2.0 value=1.0
uniform float fisheye_strength;

//@float min=10.0 max=180.0 value=90.0
uniform float fisheye_fov;

//@float min=0.0 max=1.0 value=0.5
uniform float fisheye_center_x;

//@float min=0.0 max=1.0 value=0.5
uniform float fisheye_center_y;

//@float min=0.0 max=1.0 value=0.0
uniform float fisheye_asymmetric;

//@float min=-1.0 max=1.0 value=0.0
uniform float fisheye_barrel;

//@float min=0.0 max=3.0 value=1.0
uniform float fisheye_vignette;

//@float min=0.0 max=1.0 value=0.0
uniform float fisheye_chromatic;

/**
 * Fisheye Lens Distortion
 * Applies realistic fisheye lens distortion with barrel/pincushion adjustment.
 * Features asymmetric distortion, vignette, and chromatic aberration.
 */

vec3 adjustFisheye(vec2 uv) {
    vec2 center = vec2(fisheye_center_x, fisheye_center_y);

    // Distance from center
    vec2 diff = uv - center;

    // Apply asymmetric scaling
    float scale = 1.0 + fisheye_asymmetric * 0.1;
    diff.x *= scale;
    diff.y /= scale;

    // Radial distance
    float r = length(diff);

    // FOV angle
    float max_angle = radians(fisheye_fov);

    // Fisheye projection
    float fisheye_dist;
    if (r > 0.0001) {
        // Equirectangular projection
        float normalized_r = min(r, 1.0);
        float theta = normalized_r * max_angle;
        float dist = sin(theta) / (r * max_angle / 3.14159);
        fisheye_dist = dist;
    } else {
        fisheye_dist = 1.0;
    }

    // Barrel/pincushion adjustment
    float barrel_distortion = 1.0 + fisheye_barrel * r * r;
    fisheye_dist *= barrel_distortion;

    // Apply distortion
    vec2 distorted_uv = center + diff * fisheye_strength * fisheye_dist;

    // Clamp to valid range
    distorted_uv = clamp(distorted_uv, 0.0, 1.0);

    return distorted_uv;
}

vec4 applyVignette(vec3 color, vec2 uv) {
    float dist = length((uv - vec2(0.5)) * vec2(1.5));
    float vignette = 1.0 - dist * fisheye_vignette;
    vignette = clamp(vignette, 0.0, 1.0);
    return color * vignette;
}

vec3 applyChromaticAberration(vec2 uv, vec4 input) {
    float intensity = fisheye_chromatic * 0.02;

    vec2 center = vec2(0.5);
    vec2 diff = uv - center;
    float r = length(diff);

    vec2 offset_r = normalize(diff) * intensity * r;
    vec2 offset_b = -normalize(diff) * intensity * r;

    float r_channel = texture2D(iChannel0, uv + offset_r).r;
    float g_channel = texture2D(iChannel0, uv).g;
    float b_channel = texture2D(iChannel0, uv + offset_b).b;

    return vec3(r_channel, g_channel, b_channel);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Apply fisheye distortion
    vec2 distorted_uv = adjustFisheye(uv);

    vec4 input = texture2D(iChannel0, distorted_uv);

    // Apply vignette
    vec3 color = applyVignette(input.rgb, uv);

    // Apply chromatic aberration if enabled
    if (fisheye_chromatic > 0.0) {
        color = applyChromaticAberration(uv, input);
    }

    fragColor = vec4(color, input.a);
}
